package com.codeguardian.service;
import com.codeguardian.dto.*; import com.codeguardian.entity.User; import com.codeguardian.repository.UserRepository; import jakarta.servlet.http.HttpServletRequest; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final BCryptPasswordEncoder encoder;
 @Transactional public LoginResponseDTO login(LoginRequestDTO r,HttpServletRequest req){ var u=users.findByUsernameOrEmail(r.getUsernameOrEmail(),r.getUsernameOrEmail()); if(u.isEmpty()||!"ACTIVE".equals(u.get().getStatus())||!encoder.matches(r.getPassword(),u.get().getPasswordHash())) return LoginResponseDTO.builder().success(false).message("Invalid username or password").build(); User user=u.get(); user.setLastLoginAt(LocalDateTime.now()); user.setLastLoginIp(req.getRemoteAddr()); users.save(user); cn.dev33.satoken.stp.StpUtil.login(user.getId()); return LoginResponseDTO.builder().success(true).message("Login successful").userId(user.getId()).username(user.getUsername()).realName(user.getRealName()).token(cn.dev33.satoken.stp.StpUtil.getTokenValue()).build(); }
}
